import{_ as t,o as a,c as r,a3 as d}from"./chunks/framework.Ki30n65y.js";const o="/depgate/screenshots/audit-log.png",n="/depgate/screenshots/audit-log-detail.png",m=JSON.parse('{"title":"Audit Log","description":"","frontmatter":{},"headers":[],"relativePath":"admin/audit-log.md","filePath":"admin/audit-log.md"}'),s={name:"admin/audit-log.md"};function i(h,e,c,g,l,p){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="audit-log" tabindex="-1">Audit Log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit Log&quot;">​</a></h1><p>The <strong>Audit Log</strong> records who changed what in DepGate: policies, exceptions, repositories, people, settings, and every sign-in and package check. Use it to answer &quot;who changed this policy, and when?&quot; or &quot;who signed in from this address?&quot;. Refused downloads are in the <a href="./decision-ledger">Decision Ledger</a>.</p><p>In the sidebar, choose <strong>Audit Log</strong>.</p><p><img src="'+o+'" alt="The Audit Log"></p><h2 id="what-is-recorded" tabindex="-1">What is recorded <a class="header-anchor" href="#what-is-recorded" aria-label="Permalink to &quot;What is recorded&quot;">​</a></h2><p>Entries are grouped by the page of the web interface they belong to.</p><table tabindex="0"><thead><tr><th>Group</th><th>Entries</th></tr></thead><tbody><tr><td><strong>Policies</strong></td><td>Policy created, updated (including a change from monitor to enforce) and deleted.</td></tr><tr><td><strong>Exceptions</strong></td><td>Exception added, updated and revoked.</td></tr><tr><td><strong>Waiver requests</strong></td><td>Waiver requested, updated, approved, rejected and deleted.</td></tr><tr><td><strong>Malware packages</strong></td><td>Entry added, updated and deleted; Override · Allow, Override · Block and Override · Custom entry.</td></tr><tr><td><strong>Package check</strong></td><td>Package checked: who checked which package, and what the check found.</td></tr><tr><td><strong>Namespace protection</strong></td><td>Namespace settings changed; Collision found.</td></tr><tr><td><strong>Sign in</strong></td><td>Sign-in succeeded and Sign-in failed, with the method and the reason; Password reset requested, email sent and completed; Invitation accepted; Identity linked, when a person signs in with an identity provider for the first time; Sessions revoked.</td></tr><tr><td><strong>Access</strong></td><td>User created, provisioned (added by single sign-on), deleted, disabled and enabled; Role changed; Invitation resent; Provider created, updated and deleted; Sign-in settings changed; Service account created and revoked; API key created and revoked; CI token created and revoked.</td></tr><tr><td><strong>Settings</strong></td><td>Gateway settings changed; Repository and upstream registry created, updated and deleted; Webhook created, updated and deleted; Mail settings changed; Artifact cache settings changed and Artifact cache purged; Destination created, updated and deleted; Job run requested, retried and discarded.</td></tr></tbody></table><p>Each row shows the time, the actor with their IP address (<strong>DepGate</strong> when the system acted on its own), the action, the target with its kind and version, and a one-line summary.</p><h2 id="view-the-details" tabindex="-1">View the details <a class="header-anchor" href="#view-the-details" aria-label="Permalink to &quot;View the details&quot;">​</a></h2><p>Choose a row to expand it. You see the <strong>Reasons</strong>, for example why a sign-in failed, the full <strong>Details</strong> of the change, and the actor&#39;s kind, IP address, user agent and authentication method. For an action made with a CI token, the token&#39;s metadata is shown too.</p><p><img src="'+n+'" alt="An expanded Audit Log entry"></p><h2 id="filter-and-search" tabindex="-1">Filter and search <a class="header-anchor" href="#filter-and-search" aria-label="Permalink to &quot;Filter and search&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Filter</th><th>Use it to</th></tr></thead><tbody><tr><td>Time range</td><td>The last 24 hours, 7 days, 30 days (the default), or a custom range of days.</td></tr><tr><td><strong>Feature</strong></td><td>One group from the table above.</td></tr><tr><td><strong>Action</strong></td><td>One kind of entry within the chosen feature.</td></tr><tr><td><strong>Target</strong></td><td>One kind of object: Policy, Exception, Waiver, Malware entry, Package, User, Identity provider, Service account, API key, CI token, Repository, Upstream registry, Webhook, Log streaming destination, Setting or Job.</td></tr><tr><td><strong>Target name</strong></td><td>Part of the object&#39;s name, such as a policy name, a package or an email address.</td></tr><tr><td><strong>Actor or IP</strong></td><td>Who made the change, or the address it came from.</td></tr></tbody></table><p><strong>Clear filters</strong> returns to the last 30 days.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Choose <strong>Export CSV</strong> to download the entries that match the current filters. An export stops after 10,000 entries and tells you; narrow the filters for the rest. To send entries to a SIEM as they happen, use <a href="./log-streaming">Log streaming</a>.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Entries are kept for two years (<code>AUDIT_RETENTION_DAYS</code>, 730 days by default; <code>0</code> keeps them forever). The <strong>Ledger and audit retention</strong> job removes older entries once an hour. After an upgrade, a banner at the top of the page announces the first purge a week ahead, with the number of entries it will delete.</p><p>At most 20 failed sign-ins per minute from one address are recorded; the rest are counted in the <code>depgate_login_audit_dropped_total</code> metric.</p>',19)])])}const f=t(s,[["render",i]]);export{m as __pageData,f as default};
